#include "App.hpp"
#include "model/Shortcuts.hpp"

#include <vector>
#include "Shell.hpp"
#include "Appearance.hpp"
#include "Log.hpp"
#include "Css.hpp"

#include <gtkmm/cssprovider.h>
#include <gtkmm/stylecontext.h>

#include <gtkmm/icontheme.h>
#include <gdkmm/display.h>

// The RESOURCE-PIPELINE paradigm's build-side seam. The app logo ships in a
// compiled-in GResource bundle (resources/yatze.gresource.xml -> yatze-resources.c,
// generated by glib-compile-resources). Declared extern "C" because that
// generated source compiles as C -- so its getter has C linkage and there's no
// generated header to include or keep in sync. (docs/resources-and-dialog-lifetime.md)
extern "C" GResource* yatze_resources_get_resource(void);

namespace yatze {

Glib::RefPtr<App> App::create() {
    log::init();   // area loggers up before anything logs
    return Glib::make_refptr_for_instance(new App());
}

App::App() : Gtk::Application(YATZE_APP_ID) {}   // from CMake: one place

// The SHORTCUT-REGISTRY paradigm's other consumer. Accelerators are an
// application-scope concern (they survive window construction order), so they
// bind here -- and they are driven from the pure model::shortcut_registry(), the
// same list ShortcutsDialog documents from. Register a shortcut once THERE and
// both the key and its advertised row follow; there is no second list to update
// and therefore nothing to drift. Doc-only rows (gestures) carry no action and
// are skipped -- they document without binding.
void App::on_startup() {
    Gtk::Application::on_startup();
    for (const auto& s : model::shortcut_registry()) {
        if (s.action.empty() || s.accels.empty()) continue;
        std::vector<Glib::ustring> accels(s.accels.begin(), s.accels.end());
        set_accels_for_action(s.action, accels);
    }
}

void App::on_activate() {
    // ── THE DESKTOP'S LIGHT/DARK PREFERENCE, FIRST, BEFORE ANY WINDOW ───────
    // GTK4 does not follow it on its own and Yatze does not link libadwaita,
    // so the app has to ask (see Appearance.hpp). Ahead of `new Shell()` on
    // purpose: the difference between starting dark and starting light and
    // repainting.
    //
    // It also has to be ahead of the icon theme work below. The logo is a
    // SYMBOLIC icon, which GTK recolours to the theme foreground -- so it
    // inherits the answer to this question rather than carrying an opinion of
    // its own, and that is exactly why the bundle ships one symbolic SVG
    // instead of a light and a dark PNG.
    appearance::follow_system();

    // The app stylesheet (Css.hpp): the drawer tabs' hover-reveal, the panels.
    // APPLICATION priority so our named classes beat the theme's defaults.
    if (auto display = Gdk::Display::get_default()) {
        auto css = Gtk::CssProvider::create();
        css->load_from_data(YATZE_CSS);
        Gtk::StyleContext::add_provider_for_display(
            display, css, GTK_STYLE_PROVIDER_PRIORITY_APPLICATION);
    }

    // Register the compiled-in bundle and point the icon theme at its icon
    // prefix, so set_icon_name("yatze-logo-symbolic") resolves out of the binary
    // and GTK recolours it to the theme foreground -- no icon on the user's disk.
    // NB: add_resource_path gets .../icons; GTK appends scalable/apps/ itself.
    g_resources_register(yatze_resources_get_resource());
    if (auto display = Gdk::Display::get_default()) {
        auto icons = Gtk::IconTheme::get_for_display(display);
        icons->add_resource_path(YATZE_APP_PATH "/icons");
    }

    m_shell = new Shell();       // lifetime owned by the application
    add_window(*m_shell);
    m_shell->build_ui();
    m_shell->present();
    if (auto lg = log::get(log::Area::App)) lg->info("Yatze activated");
}

}  // namespace yatze
